using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Agents.AI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

builder.Services.AddChatClient(b => b
    .UseFunctionInvocation()
    .UseOpenAIChatClient("gpt-4o-mini-2024-07-18", apiKey));

builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var chatOptions = new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 2048,
    Tools = [
        AIFunctionFactory.Create(researchTools.SearchWeb),
        AIFunctionFactory.Create(researchTools.TakeNote),
        AIFunctionFactory.Create(researchTools.GetNotes),
    ],
};

var topic = args.Length > 0 ? string.Join(' ', args) : "recent advances in quantum computing";

Console.WriteLine($"🔍 Researching: {topic}\n");

List<ChatMessage> history =
[
    new(ChatRole.System, """
        You are a research agent. Your job is to research a given topic thoroughly.
        Use the SearchWeb tool to find information, the TakeNote tool to save key findings,
        and GetNotes to review what you've collected. Search multiple angles of the topic,
        take notes on important findings, then produce a final summary.
        Always search at least 3 different queries before summarizing.
        """),
    new(ChatRole.User, $"Research this topic and provide a comprehensive summary: {topic}"),
];

var response = await chatClient.GetResponseAsync(history, chatOptions);

Console.WriteLine("\n📋 Research Summary:\n");
Console.WriteLine(response.Text);

Console.WriteLine("\n\n📝 Collected Notes:");
foreach (var note in researchTools.Notes)
{
    Console.WriteLine($"  • {note}");
}

// --- Tool definitions ---

public sealed class ResearchTools
{
    private readonly List<string> _notes = [];
    public IReadOnlyList<string> Notes => _notes;

    [Description("Searches the web for information on a query. Returns search result snippets.")]
    public string SearchWeb([Description("The search query")] string query)
    {
        // Simulated web search results for demonstration purposes.
        // In production, replace with a real search API (Bing, Google, etc.).
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        var results = query.ToLowerInvariant() switch
        {
            var q when q.Contains("quantum") && q.Contains("computing") =>
                """
                1. IBM unveiled a 1,121-qubit processor "Condor" and demonstrated error-corrected circuits.
                2. Google's Willow chip achieved below-threshold quantum error correction in Dec 2024.
                3. Microsoft announced a Majorana-based topological qubit milestone in 2025.
                4. Quantum advantage demonstrated for specific optimization and simulation tasks.
                """,
            var q when q.Contains("error correction") || q.Contains("fault tolerant") =>
                """
                1. Surface codes remain the leading approach for fault-tolerant quantum computing.
                2. IBM's roadmap targets 100,000 qubits by 2033 with modular error correction.
                3. Google demonstrated real-time error correction below the threshold on Willow.
                """,
            var q when q.Contains("application") || q.Contains("use case") =>
                """
                1. Drug discovery: quantum simulation of molecular interactions shows promise.
                2. Cryptography: post-quantum standards (ML-KEM, ML-DSA) finalized by NIST in 2024.
                3. Optimization: logistics and financial portfolio optimization being explored.
                4. Machine learning: quantum kernels for specific classification tasks under study.
                """,
            _ =>
                $"""
                1. Research on "{query}" is an active area of study.
                2. Multiple academic institutions and tech companies are publishing findings.
                3. Recent conferences have featured sessions dedicated to this topic.
                """,
        };

        return results;
    }

    [Description("Saves a research note for later reference. Use this to record key findings.")]
    public string TakeNote([Description("The note content to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note saved ({_notes.Count} total)");
        return $"Note saved. You now have {_notes.Count} note(s).";
    }

    [Description("Retrieves all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

